#!/usr/bin/env python3
# device-perms-v2: お店の端末にも「スタッフ（端末の管理）」「設定」を持たせられる
# 何度流しても同じ。元のファイルが想定と違うときは何も変えずに止まる
import hashlib, zlib, base64, json, os, shutil, sys, time
FILES = json.loads('{"supabase/functions/booking/index.ts": {"old": "222a9de2d7b70c9fb91c6c96bb7555a7", "new": "552f24448465414f0833598c12a4eee1", "data": ""}, "docs/admin/admin.js": {"old": "be9dce34b4613fb18ad2879648551ef9", "new": "221748d16fe0604305c5f22136430a98", "data": ""}, "docs/admin/index.html": {"old": "50c13240891405273661aed16dff6b42", "new": "5ffc34f104594f90b0921dd9c43dc040", "data": ""}, "tests/device_test.ts": {"old": "b8284b88edbd01865c8d415fdaf201d8", "new": "ed3698714fb5e9448001b9494fa86bd8", "data": ""}, "sql/lifeplus_devices_v2.sql": {"old": null, "new": "985075a24253d4b14bbdf386caaa89ee", "data": ""}}')
os.chdir(os.path.dirname(os.path.abspath(__file__)))
md5 = lambda b: hashlib.md5(b).hexdigest()
todo = []
for p, f in FILES.items():
    cur = md5(open(p, "rb").read()) if os.path.exists(p) else None
    if cur == f["new"]: print("済み", p); continue
    if cur != f["old"]: print("止めました：", p, "が想定と違います（", cur, "）。何も変えていません"); sys.exit(1)
    todo.append(p)
ts = time.strftime("%Y%m%d%H%M%S")
for p in todo:
    if os.path.exists(p): shutil.copy2(p, p + ".bak_" + ts)
    b = zlib.decompress(base64.b64decode(FILES[p]["data"]))
    assert md5(b) == FILES[p]["new"]
    open(p, "wb").write(b); print("更新" if FILES[p]["old"] else "追加", p)
print("device-perms-v2 OK")
